import React, { useEffect, useState } from "react";
import { User } from "firebase/auth";
import { getDatabase, ref, get } from "firebase/database";

interface PerfilProps {
  user: User;
}

const Perfil: React.FC<PerfilProps> = ({ user }) => {
  const [fotoPerfil, setFotoPerfil] = useState<string>(
    "https://i.pravatar.cc/150?img=3"
  );

  useEffect(() => {
    const db = getDatabase();
    const fotoRef = ref(db, `usuarios/${user.uid}/avatar`);
    get(fotoRef).then((snapshot) => {
      if (snapshot.exists()) setFotoPerfil(snapshot.val());
    });
  }, [user.uid]);

  return (
    <div className="p-6 bg-white min-h-screen">
      {/* Encabezado */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-800 mb-2">
          Horarios de la Semana
        </h1>
        <div className="flex gap-4">
          <button className="px-4 py-2 bg-blue-600 text-white rounded-md">
            Horarios Lunes
          </button>
          <button className="px-4 py-2 bg-blue-600 text-white rounded-md">
            Horarios Martes
          </button>
        </div>
      </div>

      <div className="space-y-8">
        {/* Sección Miércoles */}
        <section>
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">
            Horarios Miércoles
          </h2>
          <div className="bg-gray-100 p-4 rounded-md">
            <button className="px-4 py-2 bg-green-600 text-white rounded-md">
              Horarios Jueves
            </button>
          </div>
        </section>

        {/* Tabla de años */}
        <section>
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">
            Horarios jugados este mes
          </h2>
          <div className="overflow-x-auto">
            <table className="min-w-full border-collapse">
              <thead>
                <tr>
                  <th className="border-b-2 border-gray-300 p-3 text-left"></th>
                  {[
                    2016, 2017, 2018, 2020, 2021, 2022, 2023, 2024, 2025, 2026,
                    2027, 2028,
                  ].map((year) => (
                    <th
                      key={year}
                      className="border-b-2 border-gray-300 p-3 text-center"
                    >
                      {year}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td className="border-b border-gray-200 p-3 font-medium">
                    Deep Feeder
                  </td>
                  {[...Array(12)].map((_, i) => (
                    <td
                      key={i}
                      className="border-b border-gray-200 p-3 text-center"
                    >
                      -
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
        </section>

        {/* Información de perfil */}
        <section className="mt-8 p-4 bg-gray-50 rounded-lg">
          <div className="flex items-center gap-4">
            <img
              src={fotoPerfil}
              alt="Avatar"
              className="w-16 h-16 rounded-full border-2 border-blue-600"
            />
            <div>
              <h3 className="text-xl font-semibold">{user.displayName}</h3>
              <p className="text-gray-600">{user.email}</p>
              <p className="text-sm text-gray-500">
                Miembro desde:{" "}
                {new Date(user.metadata.creationTime!).toLocaleDateString()}
              </p>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
};

export default Perfil;
